/// What the tooltip shows of an item, from its `SetDefaults`.
#[derive(Clone, Copy, Debug, Default)]
pub struct Stats {
    pub rare: i8,
    pub damage: i16,
    pub crit: i8,
    pub knock_back: f32,
    pub use_style: i8,
    pub use_animation: i16,
    pub pick: i16,
    pub axe: i16,
    pub hammer: i16,
    pub tile_boost: i8,
    pub defense: i16,
    pub heal_life: i16,
    pub mana: i16,
    pub shoot_speed: f32,
    pub max_stack: u16,
    /// `headSlot`, `bodySlot`, `legSlot`: the armour picture it is drawn with, 0 for none.
    pub head_slot: i16,
    pub body_slot: i16,
    pub leg_slot: i16,
    /// `buffType` and `buffTime` (ticks) of what it gives when used.
    pub buff_type: i16,
    pub buff_time: i32,
    /// `lifeRegen` while worn.
    pub life_regen: i16,
    pub flags: u16,
}

